        private static void GetPermissions(string oldValue, string newValue, IList<IExtObject<string, string>> permissions, out string oldValues, out string newValues)
        {
            oldValues = oldValue.Replace("[A][B][H]", "[A]").Replace("[A][B]", "[A]").Replace("[B][H]", "[B]");
            newValues = newValue.Replace("[A][B][H]", "[A]").Replace("[A][B]", "[A]").Replace("[B][H]", "[B]");

            if (permissions != null)
            {
                foreach (var item in permissions)
                {
                    if (oldValues.Contains(item.Key))
                    {
                        oldValues = oldValues.Replace(item.Key, "[" + item.Value + "]");
                    }

                    if (newValues.Contains(item.Key))
                    {
                        newValues = newValues.Replace(item.Key, "[" + item.Value + "]");
                    }
                }
            }
        }

        private static bool IsPermissionValues(string oldValue, string newValue)
        {
            return (oldValue.Contains('[') && oldValue.Contains(']') || newValue.Contains('[') && newValue.Contains(']'));
        }

        public static string FormatValueDiff(string oldValue, string newValue, IList<IExtObject<string, string>> permissions)
        {
            return FormatValueDiff(oldValue, newValue, true, permissions);
        }

        public static string FormatValueDiff(string oldValue, string newValue, bool isShowOldValue, IList<IExtObject<string, string>> permissions)
        {
            var oldValues = oldValue;
            var newValues = newValue;

            if (IsPermissionValues(oldValue, newValue))
                GetPermissions(oldValue.ToUpper(), newValue.ToUpper(), permissions, out oldValues, out newValues);


            if (!isShowOldValue)
            {
                return string.Join(null, new string[] 
                {
                    "<span class=\"valuechanged\" title=\"", oldValues, " --> ", newValues, "\">", 
                    newValues, 
                    "</span>"
                });
            }
            else
            {
                if (oldValues == newValues)
                {
                    return string.Join(null, new string[] 
                    {
                        "<span class=\"valuechanged\">", 
                        newValues, 
                        "</span>"
                    });
                }

                return string.Join(null, new string[] 
                {
                    "<span class=\"valuechanged\">", 
                    newValues, 
                    "</span>",
                    "<div class=\"line\"></div>",
                    "<span class=\"valueold\">", 
                    oldValues, 
                    "</span>"
                });
            }
        }

        /// <summary>
        /// Detect the difference between 2 xml and produce one xml.
        /// </summary>
        /// <param name="oldXml"></param>
        /// <param name="newXml"></param>
        /// <returns></returns>
        public static string XmlDiff(string oldXml, string newXml, bool isShowOldValue, IList<IExtObject<string, string>> permissions, bool isP2PGameSetting = false, Dictionary<string, string> p2pStakes = null)
        {
            if (newXml == null) throw new Exception("TrackingValue is null.");

            if (!string.IsNullOrEmpty(oldXml))
            {
                oldXml = oldXml.Replace("\a", string.Empty);
            }

            if (!string.IsNullOrEmpty(newXml))
            {
                newXml = newXml.Replace("\a", string.Empty);
            }

            XmlDocument newDoc = new XmlDocument();
            newDoc.InnerXml = newXml.ToLower();

            bool hasOldXml = !string.IsNullOrEmpty(oldXml);            

            XmlDocument oldDoc = hasOldXml ? new XmlDocument() : newDoc;
            oldDoc.InnerXml = hasOldXml ? oldXml.ToLower() : oldDoc.InnerXml;

            XmlElement element = newDoc.DocumentElement;
            int count = element.HasChildNodes ? element.ChildNodes.Count : 1;

            for (int i = 0; i < count; i++)
            {
                XmlAttributeCollection oldAttributes = (count == 1) ? oldDoc.DocumentElement.Attributes : oldDoc.DocumentElement.ChildNodes[i].Attributes;
                XmlAttributeCollection newAttributes = (count == 1) ? newDoc.DocumentElement.Attributes : newDoc.DocumentElement.ChildNodes[i].Attributes;

                var p2pValue = string.Empty;

                if (isP2PGameSetting && count == 1)
                {
                    var new1 = newAttributes["stakelevel1"].Value == "1" ? p2pStakes["stakelevel1"] + " - " : string.Empty;
                    var new2 = newAttributes["stakelevel2"].Value == "1" ? p2pStakes["stakelevel2"] + " - " : string.Empty;
                    var new3 = newAttributes["stakelevel3"].Value == "1" ? p2pStakes["stakelevel3"] + " - " : string.Empty;
                    var new4 = newAttributes["stakelevel4"].Value == "1" ? p2pStakes["stakelevel4"] + " - " : string.Empty;
                    var new5 = newAttributes["stakelevel5"].Value == "1" ? p2pStakes["stakelevel5"] : string.Empty;

                    var newValues = new StringBuilder();

                    newValues.Append(new1);
                    newValues.Append(new2);
                    newValues.Append(new3);
                    newValues.Append(new4);
                    newValues.Append(new5);

                    if (hasOldXml)
                    {
                        var old1 = oldAttributes["stakelevel1"].Value == "1" ? p2pStakes["stakelevel1"] + " - " : string.Empty;
                        var old2 = oldAttributes["stakelevel2"].Value == "1" ? p2pStakes["stakelevel2"] + " - " : string.Empty;
                        var old3 = oldAttributes["stakelevel3"].Value == "1" ? p2pStakes["stakelevel3"] + " - " : string.Empty;
                        var old4 = oldAttributes["stakelevel4"].Value == "1" ? p2pStakes["stakelevel4"] + " - " : string.Empty;
                        var old5 = oldAttributes["stakelevel5"].Value == "1" ? p2pStakes["stakelevel5"] : string.Empty;

                        var oldValues = new StringBuilder();

                        oldValues.Append(old1);
                        oldValues.Append(old2);
                        oldValues.Append(old3);
                        oldValues.Append(old4);
                        oldValues.Append(old5);
                        
                        p2pValue = string.Join(null, new string[] 
                        {
                            "<span class=\"valuechanged\">",                             
                            newValues.ToString().Trim().TrimEnd('-'),
                            "</span>",
                            "<div class=\"line\"></div>",
                            "<span class=\"valueold\">", 
                            oldValues.ToString().Trim().TrimEnd('-'),
                            "</span>"
                        });
                    }
                    else
                    {
                        p2pValue = string.Join(null, new string[] 
                        {
                            "<span class=\"valuechanged\">",                             
                            newValues.ToString().Trim().TrimEnd('-'),
                            "</span>"
                        });
                    }

                    newAttributes["stakelevel1"].Value = p2pValue;           
                }

                foreach (XmlAttribute a in newAttributes)
                {
                    string newValue = a.Value;
                    XmlAttribute oldA = oldAttributes[a.Name];
                    string oldValue = oldA != null ? oldAttributes[a.Name].Value : newValue;

                    if ((newValue == oldValue || a.Name == "ip" || a.Name == "loginip") && !IsPermissionValues(oldValue, newValue)) // Don't format ip diff value.
                    {
                        continue;
                    }

                    if ((!string.IsNullOrEmpty(newValue) | !string.IsNullOrEmpty(oldValue)) && a.Name != "stakelevel1")
                    {
                        newAttributes[a.Name].Value = FormatValueDiff(oldValue, newValue, isShowOldValue, permissions);                        
                    }
                }                
            }

            return newDoc.InnerXml;

        }

        /// <summary>
        /// Gets the content of the HTML.
        /// Template file name must be follow format action_{actionid}.xslt
        /// </summary>
        /// <param name="xml">The XML.</param>
        /// <param name="actionId">The action id.</param>
