        /// <summary>
        /// Gets the content of the HTML.
        /// Template file name must be follow format action_{actionid}.xslt
        /// </summary>
        /// <param name="xml">The XML.</param>
        /// <param name="actionId">The action id.</param>
        /// <param name="uriRoot">The URI root folder containt xslt template</param>
        /// <param name="args">Custom XsltArgumentList</param>
        /// <returns>html string, if cannot found xslt return xml string</returns>
        public static string GetHtmlContent(string xml, int actionId, string uriRoot, XsltArgumentList args)
        {
            if (string.IsNullOrEmpty(xml)
                || actionId < 0)
                return string.Empty;

            string html = string.Empty;

            //get xsl tranform object from cache
            var transform = GetCompiledTransformObject(actionId, uriRoot);
            if (transform.OutputSettings != null && transform.TemporaryFiles != null)
            {
                html = GetHtmlString(xml, transform, args);
            }

            return html;
        }

        public static string GetHtmlContent(string xml, int actionId)
        {
            return GetHtmlContent(xml, actionId, string.Empty);
        }

        private static string GetHtmlString(string xml, XslCompiledTransform transform)
        {
            return GetHtmlString(xml, transform, null);
        }

        private static string GetHtmlString(string xml, XslCompiledTransform transform, XsltArgumentList args)
        {
            string html;
            using (MemoryStream stream = new MemoryStream(ASCIIEncoding.UTF8.GetBytes(xml)))
            {
                var document = new XPathDocument(stream);
                using (var writer = new StringWriter())
                {
                    if (transform != null)
                    {
                        transform.Transform(document, args, writer);
                        html = writer.ToString();
                    }
                    else
                    {
                        html = HttpUtility.HtmlEncode(xml);
                    }
                }
            }
            return html;
        }

        private static object locker = new object();
        /// <summary>
        /// Gets the compiled transform object.
        /// </summary>
        /// <param name="actionId">The action id.</param>
        /// <param name="uriRoot">The URI root.</param>
        /// <returns></returns>
        private static XslCompiledTransform GetCompiledTransformObject(int actionId, string uriRoot)
        {
            XslCompiledTransform xslCompiledTransform = null;

            var cache = CacheService.CreateInstance(CacheType.MemoryCache);
            var hash = cache.Get<Hashtable>(Constants.CacheKeyTransformObject);

            if (ReferenceEquals(hash, null))
            {
                hash = new Hashtable();
                cache.Set<Hashtable>(Constants.CacheKeyTransformObject, hash, TimeSpan.FromHours(1));
            }

            if (hash.ContainsKey(actionId))
            {
                xslCompiledTransform = hash[actionId] as XslCompiledTransform;
            }
            else
            {
                xslCompiledTransform = new XslCompiledTransform();
                if (!string.IsNullOrEmpty(uriRoot))
                {
                    string path =
                        HttpContext.Current.Server.MapPath(Path.Combine(uriRoot,
                                                                        string.Format("action_{0}.xslt", actionId)));

                    //if xslt file exist in path folder load it
                    //else load from database

                    if (File.Exists(path))
                    {
                        xslCompiledTransform.Load(path);
                    }
                    else
                    {
                        xslCompiledTransform.Load(actionId);
                    }
                }
                else
                {
                    //this is an extension method inject to class XslCompiledTransform
                    xslCompiledTransform.Load(actionId);
                }

                //if xlsCompiled transform load xsl conent successful
                if (xslCompiledTransform.OutputSettings != null)
                {
                    // Perform double checking and lock
                    if (!hash.Contains(actionId))
                    {
                        lock (locker)
                        {
                            if (!hash.Contains(actionId))
                            {
                                hash.Add(actionId, xslCompiledTransform);
                            }
                        }
                    }

                    //update cache
                    cache.Set<Hashtable>(Constants.CacheKeyTransformObject, hash, TimeSpan.FromHours(1));
                }
            }

            return xslCompiledTransform;
        }

        #region String Manipulation

        private const string AtLeast2WhiteSpace = "\\s{2,}";
        private const string OneWhiteSpace = " ";
        /// <summary>
        /// Find appearance of every word of string inside another string
        /// </summary>
        /// <param name="left"></param>
        /// <param name="right"></param>
        /// <returns>true/false</returns>
        public static bool IsMatch(string left, string right)
        {
            bool isMatch = false;
            if (!string.IsNullOrEmpty(left) && !string.IsNullOrEmpty(right))
            {
                left = left.ToLower();
                right = right.ToLower();
                //remove more than one spaces by only one space
                left = Regex.Replace(left, AtLeast2WhiteSpace, OneWhiteSpace);
                right = Regex.Replace(right, AtLeast2WhiteSpace, OneWhiteSpace);

                //check intersect
                isMatch = (left.Split(' ').ToList<string>()
                    .Intersect(right.Split(' ').ToList<string>()).Count() > 0);
            }

            return isMatch;
        }

        #endregion
